export const ARTICLES: Article[] = [
  { slug: "meaning-of-panchang", title: "Reading the Panchang: Tithi, Nakshatra, Yoga & Karana Explained", category: "Jyotisha", date: "2026-08-20", readTime: "8 min", image: "/images/aarti-night.jpg", excerpt: "The five limbs of the Hindu calendar — and how ordinary devotees can use them to choose auspicious moments.", body: ["Panchang means 'five limbs': Tithi (lunar day), Vara (weekday), Nakshatra (lunar mansion), Yoga (sun–moon union) and Karana (half-tithi). Together they describe the quality of any moment.", "For daily life, three are most practical. Tithi tells you the moon's phase-energy — Pratipada begins new projects, Purnima favours completion and gratitude, Amavasya suits pitru rites and introspection.", "Nakshatra refines this further: Rohini, Hasta, Anuradha and Revati are broadly auspicious, while Bharani, Krittika (first pada) and Ashlesha demand care. Your own Janma Nakshatra days amplify personal rituals.", "Finally, Rahukaal (inauspicious ~90 minutes daily) should be avoided for beginnings, while Abhijit Muhurat (midday ~48 minutes) is the versatile shubh window — even our homepage Panchang card shows both daily."] },
  { slug: "bhasma-aarti-guide", title: "Bhasma Aarti of Mahakaal: History, Meaning & Booking Guide", category: "Temples", date: "2026-07-11", readTime: "6 min", image: "/images/havan-fire.jpg", excerpt: "Why ash? The fierce grace of Ujjain's 4 AM ritual and how to attend it.", body: ["Of all Indian rituals, few are as otherworldly as the Bhasma Aarti: at 4 AM the doors open, damrus thunder, and the south-facing lingam is anointed with sacred ash — reminding every witness that all forms return to dust, and dust to Shiva.", "The ash (vibhuti) is prepared from consecrated cow-dung cakes, filtered through cloth and offered with mantras from the Vedas. Devotees say attending once dissolves the fear of time itself — Mahakaal, after all, is the Lord beyond time.", "Practical guide: book on the temple portal 2–4 weeks ahead, report by 2:30 AM in dhoti/saree with photo ID, and expect 2 hours of profound chanting. Our pandit team in Ujjain assists DivyaDhara pilgrims with the full process." ] },
  { slug: "char-dham-yatra-preparation", title: "Char Dham Yatra Preparation: Fitness, Packing & Sacred Etiquette", category: "Yatra", date: "2026-06-02", readTime: "10 min", image: "/images/yatra-himalaya.jpg", excerpt: "Altitude, weather and devotion — a complete checklist for Yamunotri to Badrinath.", body: ["The Char Dham is high, cold and magnificent. Begin walking 3–4 km daily a month before; practise breathing exercises for altitudes above 3,000 m. Those with cardiac or respiratory conditions must consult doctors — helicopter options reduce strain dramatically.", "Pack in layers: thermal inners, fleece, down jacket, rain shell, woollen cap, gloves, trekking shoes (broken in), headlamp, dry fruits, ORS and personal medicines. Doli, pony and palki rates are fixed by the administration — insist on printed receipts.", "Sacred etiquette: bathe before darshan where possible, avoid leather in sanctums, never photograph restricted garbhagrihas, and carry back every wrapper — the Mandakini and Alaknanda are goddesses, not dustbins."] },
  { slug: "griha-pravesh-muhurat-2026", title: "Griha Pravesh Muhurats 2026–27: Months, Nakshatras & Rules", category: "Sanskar", date: "2026-09-01", readTime: "7 min", image: "/images/ashram-dawn.jpg", excerpt: "Which months are truly shubh for house-warming — and the five rules priests check first.", body: ["Traditional texts favour Magha, Phalguna, Vaishakha and Jyeshtha for Griha Pravesh, while the Chaturmasya (Shravan–Kartik) is generally avoided unless the family priest finds exceptional bala.", "The five checks: auspicious weekday (Mon/Wed/Thu/Fri), shubh nakshatra (Rohini, Mrigashira, Uttarashadha among favourites), freedom from Bhadra, the house-owner's tara-bala, and Vastu-purush orientation for the entry.", "Remember: muhurat is personal. Two families can have different ideal dates for the same house — always compute from the grihaswami's janma nakshatra. Our pandits include this computation free with every Griha Pravesh booking."] },
  { slug: "sanskrit-for-beginners", title: "Sanskrit in 15 Minutes a Day: A Beginner's Path", category: "Learning", date: "2026-05-14", readTime: "5 min", image: "/images/temple-corridor.jpg", excerpt: "The language of the mantras is closer than you think — start with sound, not grammar.", body: ["Begin with shravana (listening): chant one shloka daily with audio before touching grammar. Sound first, script second, sutras last — this mirrors how rishis transmitted the language for millennia.", "Master the 13 vowels and 33 consonants with correct mouth positions (mukha-sthana); half of 'difficult Sanskrit' is simply mispronounced Sanskrit.", "Join a sambhashanam circle early — even ten spoken sentences rewire your relationship with every stotra you will ever chant. Our 12-week foundation batch starts monthly."] }
];

